g=[[0]*18 for _ in range(16)]
for r in range(16):
 for c in [2,7,11,16]: g[r][c]=2
for r in range(1,4):
 for c in range(1,4): g[r][c]=3
g[2][2]=2
for r in range(11,14):
 for c in range(10,13): g[r][c]=3
g[12][11]=2
# horizontal rays, paint zeros only
for r,cc in [(2,2),(12,11)]:
 for c in range(18):
  if g[r][c]==0: g[r][c]=1
# patches at intersections of rays with vertical lines except the object's own center; center remains 2
for r,object_col in [(2,2),(12,11)]:
 for c in [2,7,11,16]:
  if c==object_col: continue
  for rr in range(r-1,r+2):
   for cc in range(c-1,c+2):
    if rr==r and cc==c: continue
    g[rr][cc]=1
print('\n'.join(' '.join(map(str,row)) for row in g))
